#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> scoreValidator(std::vector<std::string>& events) {
        int score = 0, counter = 0;
        for (const std::string& e : events) {
            if (e == "W") {
                counter++;
                if (counter == 10) break;
            } else if (e == "WD" || e == "NB") {
                score++;
            } else {
                score += std::stoi(e);
            }
        }
        return {score, counter};
    }
};

class Solution {
    public int[] scoreValidator(String[] events) {
        int score = 0, counter = 0;
        for (String e : events) {
            if (e.equals("W")) {
                counter++;
                if (counter == 10) break;
            } else if (e.equals("WD") || e.equals("NB")) {
                score++;
            } else {
                score += Integer.parseInt(e);
            }
        }
        return new int[]{score, counter};
    }
}

function scoreValidator(events) {
    let score = 0, counter = 0;
    for (const e of events) {
        if (e === "W") {
            counter++;
            if (counter === 10) break;
        } else if (e === "WD" || e === "NB") {
            score++;
        } else {
            score += Number(e);
        }
    }
    return [score, counter];
}
